@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap");
:root {
  --bg-core: #0b0d13;
  --bg-card: #13161f;
  --border-card: #1c202d;
  --border-light: rgba(255, 255, 255, 0.05);
  --text-primary: #f1f3f7;
  --text-secondary: #9aa1b2;
  --text-muted: #5e6577;
  --accent-purple: #6366f1;
  --accent-purple-hover: #4f46e5;
  --spark-peach: #e08a68;
  --stage-purple: #7c3aed;
  --stage-amber: #eab308;
  --stage-mint: #10b981;
  --stage-sky: #06b6d4;
  --stage-blue: #3b82f6;
  --today-glow: #38bdf8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-core);
  color: var(--text-primary);
  font-family: "Inter", -apple-system, BlinkMacSystemFont, sans-serif;
  padding: 12px 16px;
  margin: 0;
  width: 100%;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
}

.dash-canvas {
  width: 100%;
  max-width: 100%;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Masthead Header */
.masthead {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding-bottom: 4px;
}

.breadcrumbs {
  font-size: 0.78rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.crumb-sep {
  color: var(--border-card);
}

.crumb-current {
  color: var(--text-secondary);
}

.title-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.page-title {
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #fff;
}

.meta-tag {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.75rem;
  font-weight: 500;
  padding: 3px 9px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-secondary);
  border: 1px solid var(--border-card);
}

.tag-status {
  background: rgba(16, 185, 129, 0.1);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.25);
  font-weight: 600;
}

.controls-row {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 10px;
}

.cycle-select-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.select-ico {
  position: absolute;
  left: 10px;
  color: var(--text-muted);
  pointer-events: none;
}

.cycle-dropdown {
  appearance: none;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-card);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 0.82rem;
  padding: 6px 28px 6px 30px;
  cursor: pointer;
  outline: none;
  font-family: inherit;
  transition: border-color 0.15s ease;
}

.cycle-dropdown:hover {
  border-color: rgba(255, 255, 255, 0.15);
}

.meta-item-text {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.masthead-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn-primary, .btn-secondary {
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 9px 16px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-primary);
  border: 1px solid var(--border-card);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.07);
}

.btn-primary {
  background: var(--accent-purple);
  color: #fff;
}

.btn-primary:hover {
  background: var(--accent-purple-hover);
}

/* Metric Strip (5 Boxes) */
.metric-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}

.card-box {
  background: var(--bg-card);
  border: 1px solid var(--border-card);
  border-radius: 10px;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.box-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.box-label {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-weight: 500;
}

.spark-line {
  width: 76px;
  height: 24px;
}

.box-val {
  font-size: 1.85rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #fff;
}

.box-val .val-unit {
  font-size: 1.05rem;
  color: var(--text-muted);
  font-weight: 500;
}

.box-sub {
  font-size: 0.76rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 4px;
}

.sub-arrow {
  color: var(--text-muted);
}

/* Common Card Panel */
.card-panel {
  background: var(--bg-card);
  border: 1px solid var(--border-card);
  border-radius: 12px;
  padding: 20px 24px;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 14px;
}

.panel-heading {
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: #fff;
}

.panel-stat-summary {
  display: flex;
  gap: 20px;
  font-size: 0.82rem;
  color: var(--text-muted);
}

.stat-pair b {
  color: var(--text-primary);
  font-weight: 600;
}

.chart-legend {
  display: flex;
  align-items: center;
  gap: 16px;
}

.legend-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.78rem;
  color: var(--text-secondary);
}

.legend-line {
  width: 18px;
  height: 2.5px;
  border-radius: 2px;
}

.legend-solid {
  background: #6366f1;
}

.legend-dotted {
  background: #eab308;
}

/* Chart Viewport */
.chart-viewport {
  position: relative;
  width: 100%;
  margin-top: 6px;
}

.spline-svg {
  width: 100%;
  height: 210px;
}

.grid-lines line {
  stroke: rgba(255, 255, 255, 0.04);
  stroke-dasharray: 4 4;
}

.axis-dates {
  display: flex;
  justify-content: space-between;
  padding: 8px 6px 0 6px;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.7rem;
  color: var(--text-muted);
}

/* Floating Chart Tooltip Pill */
.chart-tooltip {
  position: absolute;
  top: 16px;
  left: 56%;
  background: #191e2b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.6);
  border-radius: 8px;
  padding: 10px 14px;
  pointer-events: none;
  min-width: 170px;
}

.tt-date {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.72rem;
  color: var(--text-secondary);
}

.tt-tag {
  display: inline-block;
  font-size: 0.65rem;
  font-weight: 600;
  color: #34d399;
  background: rgba(16, 185, 129, 0.12);
  padding: 1px 6px;
  border-radius: 4px;
  margin: 4px 0 6px 0;
}

.tt-grid {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.tt-k {
  display: block;
  font-size: 0.65rem;
  color: var(--text-muted);
}

.tt-v {
  display: block;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.8rem;
  font-weight: 600;
  color: #fff;
}

/* Lower Split Layout */
.lower-layout {
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 16px;
}

.table-wrap {
  overflow-x: auto;
  max-height: 310px;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

.data-table th {
  padding: 10px 14px;
  font-size: 0.74rem;
  font-weight: 500;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border-card);
}

.data-table td {
  padding: 12px 14px;
  font-size: 0.82rem;
  color: var(--text-secondary);
  border-bottom: 1px solid rgba(255, 255, 255, 0.025);
  font-family: "JetBrains Mono", monospace;
}

.data-table tr:hover td {
  background: rgba(255, 255, 255, 0.02);
  color: #fff;
}

/* Current Day Highlight */
.data-table tr.today-row td {
  background: rgba(56, 189, 248, 0.08) !important;
  color: #fff !important;
  border-top: 1px solid var(--today-glow) !important;
  border-bottom: 1px solid var(--today-glow) !important;
}

.data-table tr.today-row td:first-child {
  border-left: 2px solid var(--today-glow) !important;
  border-top-left-radius: 6px;
  border-bottom-left-radius: 6px;
}

.data-table tr.today-row td:last-child {
  border-right: 2px solid var(--today-glow) !important;
  border-top-right-radius: 6px;
  border-bottom-right-radius: 6px;
}

.today-pip-tag {
  background: var(--today-glow);
  color: #0b0d13;
  font-weight: 700;
  font-size: 0.62rem;
  padding: 1px 5px;
  border-radius: 3px;
  margin-left: 6px;
}

.data-table tr.weekend-row td {
  background: rgba(0, 0, 0, 0.2);
  color: var(--text-muted);
}

.status-badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 500;
}

.badge-auto {
  background: rgba(99, 102, 241, 0.12);
  color: #818cf8;
}

.badge-backfill {
  background: rgba(168, 85, 247, 0.12);
  color: #c084fc;
}

.badge-off {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-muted);
}

/* Pipeline Stages List (1:1 with reference) */
.pipeline-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 4px;
}

.pipeline-row {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pipeline-meta {
  display: flex;
  justify-content: space-between;
  font-size: 0.78rem;
}

.stage-label {
  color: var(--text-secondary);
  font-weight: 500;
}

.stage-val {
  font-family: "JetBrains Mono", monospace;
  color: var(--text-primary);
  font-weight: 600;
}

.bar-track {
  width: 100%;
  height: 9px;
  background: #1b1f2b;
  border-radius: 9999px;
  overflow: hidden;
}

.bar-thumb {
  height: 100%;
  border-radius: 9999px;
  transition: width 0.6s ease;
}

.bar-purple {
  background: var(--stage-purple);
}

.bar-amber {
  background: var(--stage-amber);
}

.bar-mint {
  background: var(--stage-mint);
}

.bar-sky {
  background: var(--stage-sky);
}

.bar-blue {
  background: var(--stage-blue);
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
}

.modal-card {
  background: #141722;
  border: 1px solid var(--border-card);
  border-radius: 12px;
  padding: 24px;
  width: 90%;
  max-width: 420px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: #fff;
}

.modal-x {
  background: none;
  border: none;
  font-size: 1.4rem;
  color: var(--text-muted);
  cursor: pointer;
}

.modal-lead {
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin: 8px 0 16px 0;
}

.modal-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 20px;
}

.field-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.field-item label {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.field-item input {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-card);
  border-radius: 6px;
  padding: 8px 12px;
  color: #fff;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.88rem;
}

.modal-foot {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.spline-svg {
  width: 100%;
  height: 220px;
  display: block;
}

