let allDbRecords = [];
let selectedCycleStart = "2026-09-03";
let extraSick = 0.00;
let extraAnnual = 0.00;
let overrideRate = 36.7861;
appsmith.onReady(() => {
  init();
});
appsmith.onModelChange(model => {
  if (model) {
    allDbRecords = model.allRecords || [];
    if (model.hourlyRate) {
      overrideRate = parseFloat(model.hourlyRate);
    }
  }
  render();
});
function init() {
  const model = appsmith.model || {};
  allDbRecords = model.allRecords || [];
  if (model.hourlyRate) {
    overrideRate = parseFloat(model.hourlyRate);
  }
  render();
}
function onCycleChange(val) {
  selectedCycleStart = val;
  render();
}
function openLeaveModal() {
  const modal = document.getElementById("leave-modal");
  if (modal) modal.style.display = "flex";
}
function closeLeaveModal() {
  const modal = document.getElementById("leave-modal");
  if (modal) modal.style.display = "none";
}
function applyParameters() {
  const sickInput = document.getElementById("input-sick-hrs");
  const annualInput = document.getElementById("input-annual-hrs");
  const rateInput = document.getElementById("input-rate-override");
  if (sickInput) extraSick = parseFloat(sickInput.value) || 0.0;
  if (annualInput) extraAnnual = parseFloat(annualInput.value) || 0.0;
  if (rateInput) overrideRate = parseFloat(rateInput.value) || 36.7861;
  closeLeaveModal();
  render();
}
function calculatePAYG(gross) {
  if (gross <= 738) return 0;
  if (gross <= 1730) return (gross - 738) * 0.16;
  if (gross <= 5192) return 158.72 + (gross - 1730) * 0.30;
  return 1197.32 + (gross - 5192) * 0.37;
}
function formatDateLocal(d) {
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}
function getTodayStr() {
  return formatDateLocal(new Date());
}
function build14DayWindow(startDateStr) {
  const parts = startDateStr.split("-").map(Number);
  const start = new Date(parts[0], parts[1] - 1, parts[2], 12, 0, 0);
  const daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const list = [];
  const recordMap = {};
  allDbRecords.forEach(r => {
    const rawDate = (r["Date"] || r.date || r.work_date || "").slice(0, 10).trim();
    if (rawDate) {
      recordMap[rawDate] = r;
    }
  });
  for (let i = 0; i < 14; i++) {
    const cur = new Date(start);
    cur.setDate(start.getDate() + i);
    const dateStr = formatDateLocal(cur);
    const dayName = daysOfWeek[cur.getDay()];
    const isWeekend = cur.getDay() === 0 || cur.getDay() === 6;
    if (recordMap[dateStr]) {
      const match = recordMap[dateStr];
      list.push({
        Date: dateStr,
        Day: dayName,
        "Start Time": match["Start Time"] || match.start_time || "-",
        "Finish Time": match["Finish Time"] || match.finish_time || "-",
        "Meal Break": match["Meal Break"] || match.meal_break || "-",
        "Total Ordinary Hours": parseFloat(match["Total Ordinary Hours"] || match.total_hours) || 0.0,
        Status: match["Status"] || match.status || "Logged"
      });
    } else {
      list.push({
        Date: dateStr,
        Day: dayName,
        "Start Time": "-",
        "Finish Time": "-",
        "Meal Break": "-",
        "Total Ordinary Hours": 0.0,
        Status: isWeekend ? "Weekend / Off" : "Absent / Off"
      });
    }
  }
  return list;
}
function render() {
  const rate = overrideRate;
  const today = getTodayStr();
  const fortnightRecords = build14DayWindow(selectedCycleStart);
  const entitlements = appsmith.model && appsmith.model.entitlements || {
    sickBalance: 87.86,
    annualBalance: 220.31
  };
  let totalLogged = 0;
  let remainingWorkdays = 0;
  const dailySeries = [];
  fortnightRecords.forEach(r => {
    const h = parseFloat(r["Total Ordinary Hours"]) || 0.0;
    totalLogged += h;
    dailySeries.push(h);
    const d = r["Date"];
    const day = r["Day"];
    const isWk = day === "Saturday" || day === "Sunday";
    if (!isWk && d >= today && h === 0) {
      remainingWorkdays++;
    }
  });
  const totalEffectiveHours = totalLogged + extraSick + extraAnnual;
  const targetQuota = 80.0;
  const remainingHours = Math.max(0, targetQuota - totalEffectiveHours);
  const quotaPercent = Math.min(100, totalEffectiveHours / targetQuota * 100);
  const elTotalHrs = document.getElementById("val-total-hours");
  if (elTotalHrs) elTotalHrs.innerText = totalEffectiveHours.toFixed(2);
  const elRemHrs = document.getElementById("val-remaining-hours");
  if (elRemHrs) elRemHrs.innerText = remainingHours.toFixed(2);
  const elPace = document.getElementById("trend-pace");
  if (elPace) {
    const pace = remainingWorkdays > 0 ? (remainingHours / remainingWorkdays).toFixed(2) : "0.00";
    elPace.innerText = remainingHours > 0 ? `Target: ${pace}h / day` : `Quota Achieved!`;
  }
  const gross = totalEffectiveHours * rate;
  const payg = calculatePAYG(gross);
  const net = gross - payg;
  const superContrib = gross * 0.12;
  const elGross = document.getElementById("val-gross-accrual");
  if (elGross) {
    elGross.innerText = `$${gross.toLocaleString("en-AU", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;
  }
  const elNet = document.getElementById("val-net-payout");
  if (elNet) {
    elNet.innerText = `$${net.toLocaleString("en-AU", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;
  }
  const elTax = document.getElementById("trend-tax");
  if (elTax) elTax.innerText = `PAYG: -$${payg.toFixed(2)}`;
  const remSick = Math.max(0, entitlements.sickBalance - extraSick);
  const elSick = document.getElementById("val-sick-balance");
  if (elSick) {
    elSick.innerHTML = `${remSick.toFixed(2)} <span class="val-unit">h</span>`;
  }
  const elSickTrend = document.getElementById("trend-sick");
  if (elSickTrend) {
    elSickTrend.innerText = `${(remSick / 8).toFixed(1)} days available`;
  }
  const elHeadRate = document.getElementById("head-rate");
  if (elHeadRate) elHeadRate.innerText = `$${rate.toFixed(2)}`;
  const elHeadProj = document.getElementById("head-projected");
  if (elHeadProj) {
    elHeadProj.innerText = `$${gross.toLocaleString("en-AU", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;
  }
  drawSparkline("spark-1", dailySeries);
  drawSparkline("spark-2", dailySeries.map(h => Math.max(0, 8 - h)));
  drawSparkline("spark-3", dailySeries.map(h => h * rate));
  drawSparkline("spark-4", dailySeries.map(h => h * rate * 0.8));
  drawSparkline("spark-5", [87.86, 87.86, 87.86, remSick]);
  renderSplineChart(fortnightRecords, dailySeries);
  const elQuotaVal = document.getElementById("stage-quota-val");
  if (elQuotaVal) elQuotaVal.innerText = `${totalEffectiveHours.toFixed(2)} (${quotaPercent.toFixed(1)}%)`;
  const elQuotaBar = document.getElementById("stage-quota-bar");
  if (elQuotaBar) elQuotaBar.style.width = `${quotaPercent}%`;
  const elStageSick = document.getElementById("stage-sick-val");
  if (elStageSick) elStageSick.innerText = `${remSick.toFixed(2)} hrs (${(remSick / 8).toFixed(1)} days)`;
  const elStageSuper = document.getElementById("stage-super-val");
  if (elStageSuper) elStageSuper.innerText = `$${superContrib.toFixed(2)} (12.0%)`;
  const elStageSuperBar = document.getElementById("stage-super-bar");
  if (elStageSuperBar) elStageSuperBar.style.width = `${quotaPercent}%`;
  const elStagePayg = document.getElementById("stage-payg-val");
  if (elStagePayg) elStagePayg.innerText = `-$${payg.toFixed(2)}`;
  const elStagePaygBar = document.getElementById("stage-payg-bar");
  if (elStagePaygBar) elStagePaygBar.style.width = `${quotaPercent}%`;
  const tbody = document.getElementById("timesheet-body");
  if (tbody) {
    tbody.innerHTML = "";
    fortnightRecords.forEach(r => {
      const tr = document.createElement("tr");
      const date = r["Date"];
      const day = r["Day"];
      const isWk = day === "Saturday" || day === "Sunday";
      const isToday = date === today;
      if (isWk) tr.classList.add("weekend-row");
      if (isToday) tr.classList.add("today-row");
      const status = r["Status"] || "-";
      let bClass = "badge-off";
      if (status === "Auto") bClass = "badge-auto";else if (status === "Backfill") bClass = "badge-backfill";
      const hrs = r["Total Ordinary Hours"];
