function calculatePAYG(gross) {
  if (gross <= 738) return 0;
  if (gross <= 1730) return (gross - 738) * 0.16;
  if (gross <= 5192) return 158.72 + (gross - 1730) * 0.30;
  return 1197.32 + (gross - 5192) * 0.37;
}

function formatDateLocal(d) {
  const year = d.getFullYear();
