  if (elHeadRate) elHeadRate.innerText = `$${rate.toFixed(2)}`;

  const elHeadProj = document.getElementById("head-projected");
  if (elHeadProj) {
    elHeadProj.innerText = `$${gross.toLocaleString("en-AU", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }

  drawSparkline("spark-1", dailySeries);
  drawSparkline("spark-2", dailySeries.map((h) => Math.max(0, 8 - h)));
  drawSparkline("spark-3", dailySeries.map((h) => h * rate));
  drawSparkline("spark-4", dailySeries.map((h) => h * rate * 0.8));
  drawSparkline("spark-5", [87.86, 87.86, 87.86, remSick]);

  renderSplineChart(fortnightRecords, dailySeries);

  const elQuotaVal = document.getElementById("stage-quota-val");
  if (elQuotaVal) elQuotaVal.innerText = `${totalEffectiveHours.toFixed(2)} (${quotaPercent.toFixed(1)}%)`;

  const elQuotaBar = document.getElementById("stage-quota-bar");
  if (elQuotaBar) elQuotaBar.style.width = `${quotaPercent}%`;

  const elStageSick = document.getElementById("stage-sick-val");
  if (elStageSick) elStageSick.innerText = `${remSick.toFixed(2)} hrs (${(remSick / 8).toFixed(1)} days)`;

  const elStageSuper = document.getElementById("stage-super-val");
  if (elStageSuper) elStageSuper.innerText = `$${superContrib.toFixed(2)} (12.0%)`;

  const elStageSuperBar = document.getElementById("stage-super-bar");
  if (elStageSuperBar) elStageSuperBar.style.width = `${quotaPercent}%`;

  const elStagePayg = document.getElementById("stage-payg-val");
  if (elStagePayg) elStagePayg.innerText = `-$${payg.toFixed(2)}`;

  const elStagePaygBar = document.getElementById("stage-payg-bar");
  if (elStagePaygBar) elStagePaygBar.style.width = `${quotaPercent}%`;

  const tbody = document.getElementById("timesheet-body");
  if (tbody) {
    tbody.innerHTML = "";
    fortnightRecords.forEach((r) => {
      const tr = document.createElement("tr");
      const date = r["Date"];
      const day = r["Day"];
      const isWk = day === "Saturday" || day === "Sunday";
      const isToday = date === today;

      if (isWk) tr.classList.add("weekend-row");
      if (isToday) tr.classList.add("today-row");

      const status = r["Status"] || "-";
      let bClass = "badge-off";
      if (status === "Auto") bClass = "badge-auto";
      else if (status === "Backfill") bClass = "badge-backfill";

      const hrs = r["Total Ordinary Hours"];

      tr.innerHTML = `
        <td>${date} ${isToday ? '<span class="today-pip-tag">TODAY</span>' : ""}</td>
        <td style="font-weight:500;">${day}</td>
        <td>${r["Start Time"]}</td>
        <td>${r["Finish Time"]}</td>
        <td>${r["Meal Break"]}</td>
        <td style="font-weight:600; color:${hrs > 0 ? "#6366f1" : "inherit"}">${hrs > 0 ? hrs.toFixed(2) : "-"}</td>
        <td><span class="status-badge ${bClass}">${status}</span></td>
      `;
      tbody.appendChild(tr);
    });
  }
}

function drawSparkline(id, arr) {
  const svg = document.getElementById(id);
  if (!svg || !arr.length) return;
  const max = Math.max(...arr, 1);
  const min = Math.min(...arr, 0);
  const w = 80;
  const h = 26;

  const pts = arr
    .map((v, i) => {
      const x = (i / (arr.length - 1 || 1)) * w;
      const y = h - ((v - min) / (max - min || 1)) * (h - 6) - 3;
      return `${x},${y}`;
    })
    .join(" ");

  svg.innerHTML = `<polyline fill="none" stroke="#e08a68" stroke-width="1.8" points="${pts}" stroke-linecap="round" stroke-linejoin="round"/>`;
}

function renderSplineChart(records, dailySeries) {
  const layer = document.getElementById("svg-chart-layers");
  const dates = document.getElementById("axis-dates");
  if (!layer || !dates) return;

  const count = records.length || 14;
  const w = 1000;
  const h = 210;
  const pts = [];

  dates.innerHTML = "";
  records.forEach((r, i) => {
    const x = (i / (count - 1 || 1)) * w;
    const hrs = dailySeries[i] || 0;
    const y = h - (hrs / 10.0) * 150 - 25;
    pts.push({ x, y, hrs, date: r["Date"] });

    const span = document.createElement("span");
    span.innerText = (r["Date"] || "").slice(5);
    dates.appendChild(span);
  });

  const targetY = h - (8.0 / 10.0) * 150 - 25;
  let svg = `<line x1="0" y1="${targetY}" x2="1000" y2="${targetY}" stroke="#eab308" stroke-width="1.8" stroke-dasharray="5 5"/>`;

  const spline = pts.reduce((acc, p, i, a) => {
    if (i === 0) return `M ${p.x} ${p.y}`;
    const prev = a[i - 1];
    const cx = (prev.x + p.x) / 2;
    return `${acc} C ${cx} ${prev.y}, ${cx} ${p.y}, ${p.x} ${p.y}`;
  }, "");

  svg += `<path d="${spline} L 1000 210 L 0 210 Z" fill="url(#purpleGlow)"/>`;
  svg += `<path d="${spline}" fill="none" stroke="#6366f1" stroke-width="2.5"/>`;

  pts.forEach((p) => {
    if (p.hrs > 0) {
      svg += `<circle cx="${p.x}" cy="${p.y}" r="3.5" fill="#13161f" stroke="#6366f1" stroke-width="2"/>`;
    }
  });

  layer.innerHTML = svg;
}
